INSERT INTO `brands` (`id`, `slug`, `name`, `tagline`, `description`, `focus`, `website_url`, `affiliate_url`, `accent`, `is_sponsor`, `verified`, `status`, `created_at`, `updated_at`) VALUES ('karcher', 'karcher', 'Kärcher', 'Профессиональная техника для клининга', 'Мировой лидер в производстве клининговой техники: экстракторы, парогенераторы, поломоечные машины. Официальный сервис и склад запчастей в Минске.', 'technika', 'https://www.karcher.by/', 'https://www.karcher.by/', '#FFC800', 0, 0, 'published', 1787830703100, 1787830703100);
