INSERT INTO `cleaning_companies` (`id`, `slug`, `name`, `legal_name`, `country_code`, `region`, `city`, `address`, `description`, `website_url`, `phone`, `email`, `telegram_url`, `price_from`, `price_unit`, `experience_years`, `cover_image`, `tags`, `guarantees`, `verified`, `promoted`, `status`, `created_at`, `updated_at`) VALUES ('spectrclean', 'spectrclean', 'Спектр Клининг', NULL, 'BY', 'Минская', 'Минск', NULL, 'Профессиональный клининг для бизнеса и дома в Минске: регулярная уборка по договору, генеральная и послестроительная уборка. Специализация — пищевые производства, серверные, склады.', 'https://spectrclean.by', '+375 29 186-98-88', 'info@spectrclean.by', 'https://t.me/Spectr_Cleaning_Bot', 6, 'м²', 7, 'https://picsum.photos/seed/spectrclean/800/600', '["Работает по договору","7+ лет на рынке","350+ клиентов"]', '["Фиксированная цена по договору"]', 1, 0, 'published', 1787830703100, 1787830703100);
INSERT INTO `cleaning_companies` (`id`, `slug`, `name`, `legal_name`, `country_code`, `region`, `city`, `address`, `description`, `website_url`, `phone`, `email`, `telegram_url`, `price_from`, `price_unit`, `experience_years`, `cover_image`, `tags`, `guarantees`, `verified`, `promoted`, `status`, `created_at`, `updated_at`) VALUES ('freshclean', 'freshclean', 'FreshClean', NULL, 'BY', 'Минская', 'Минск', NULL, 'Уборка квартир, домов, офисов и коммерческой недвижимости по всей Беларуси. Итоговая стоимость рассчитывается индивидуально в зависимости от площади и степени загрязнения.', 'https://freshclean.by', '+375 25 525-76-10', 'info@freshclean.by', NULL, 3, 'м²', 5, 'https://picsum.photos/seed/freshclean/800/600', '["Работает по всей Беларуси","Индивидуальный расчёт стоимости"]', NULL, 1, 0, 'published', 1787830703100, 1787830703100);
INSERT INTO `cleaning_companies` (`id`, `slug`, `name`, `legal_name`, `country_code`, `region`, `city`, `address`, `description`, `website_url`, `phone`, `email`, `telegram_url`, `price_from`, `price_unit`, `experience_years`, `cover_image`, `tags`, `guarantees`, `verified`, `promoted`, `status`, `created_at`, `updated_at`) VALUES ('kitt', 'chistiy-kit', 'Чистый Кит (CleanWhale)', NULL, 'BY', 'Минская', 'Минск', NULL, 'Уборка квартир, мойка окон, химчистка и уборка после ремонта в Минске. Работает по системе онлайн-бронирования с выбором клинера; регулярная уборка обходится дешевле разовой.', 'https://kitt.by', NULL, NULL, NULL, 94.99, NULL, NULL, 'https://picsum.photos/seed/kitt/800/600', '["Онлайн-бронирование","Скидки при регулярной уборке"]', NULL, 0, 0, 'published', 1787830703100, 1787830703100);
